/* 原创同步例题与练习。章节依据用户提供的目录，建议课时按内容组织。 */
const curriculum=[
 {name:'三角形',sections:['认识三角形','图形的全等','探索三角形全等的条件','三角形的尺规作图','利用三角形全等测距离']},
 {name:'轴对称',sections:['轴对称现象','探索轴对称的性质','简单的轴对称图形','利用轴对称进行设计']},
 {name:'勾股定理',sections:['探索勾股定理','一定是直角三角形吗','勾股定理的应用举例']},
 {name:'实数',sections:['无理数','平方根','立方根','估算','用计算器开方','实数']},
 {name:'位置与坐标',sections:['确定位置','平面直角坐标系','轴对称与坐标变化']},
 {name:'一次函数',sections:['函数','一次函数','一次函数的图象','确定一次函数的表达式','一次函数的应用']}
];
const topics=[];
const Q=(type,text,answer,steps,options=[],diagram=null)=>({type,text,answer,steps,options,diagram});
function T(section,name,rule,method,pitfall,example,basic,improve,challenge){const id='t'+String(topics.length+1).padStart(2,'0');const [chapter,part]=section.split('.').map(Number);const questions=[basic,improve,challenge].map((q,i)=>({...q,id:id+'-'+(i+1),difficulty:['基础题','提高题','压轴题'][i],topicId:id,chapter,section}));topics.push({id,section,chapter,part,name,rule,method,pitfall,example,questions});}
T('1.1','三边关系与第三边范围','两边为 a、b 时，第三边 c 满足 |a−b|＜c＜a+b。','先求严格范围，再结合整数、周长或等腰条件筛选。','两端不能取等号；等腰条件需区分底边和腰。',
Q('解答题','三角形两边长为 4 和 7，第三边 x 为整数，求 x 的所有可能值。','4，5，6，7，8，9，10',['由三边关系，3＜x＜11。','整数 x=4，5，6，7，8，9，10，共 7 个。']),
Q('选择题','下列各组线段长度中，能组成三角形的是（　）。','B',['比较较小两边之和与最大边。A、D 恰好相等，C 的和小于最大边，均不能组成三角形。','B 中 3+4＞5，能组成三角形。'],['2，3，5','3，4，5','1，2，4','2，2，4']),
Q('填空题','三角形两边长为 5、8，第三边为偶数，则第三边共有____种可能。','5',['由三边关系，3＜x＜13。','满足条件的偶数为 4、6、8、10、12，共 5 个。']),
Q('解答题','等腰三角形周长为 20，其中一边长为 6。求所有可能的三边长。','6，6，8 或 7，7，6',['当 6 为腰时，底边为 20−12=8，6+6＞8，成立。','当 6 为底边时，两腰各为 (20−6)÷2=7，成立。','所以有两种可能。']));
T('1.1','内角和、外角与角平分线','内角和为 180°；外角等于与它不相邻的两个内角的和。','明确角所在的三角形，再列等式；角平分线对应一半角度。','外角关系不包含相邻内角。',
Q('计算题','△ABC 中，∠A=48°，∠B=67°，求 ∠C。','65°',['三角形内角和为 180°。','∠C=180°−48°−67°=65°。']),
Q('选择题','一个三角形的两个内角为 35°、75°，第三个内角为（　）。','C',['第三角=180°−35°−75°=70°。'],['60°','65°','70°','110°']),
Q('计算题','△ABC 中，∠A=2∠B，C 点处的外角为 120°，求三个内角。','∠A=80°，∠B=40°，∠C=60°',['设 ∠B=x，由外角性质得 2x+x=120°，x=40°。','∠A=80°；∠C=180°−120°=60°。']),
Q('证明题','△ABC 的内角平分线 BD、CE 相交于内部点 I。若 ∠A=50°，求 ∠BIC 并说明理由。','115°',['∠ABC+∠ACB=130°。','角平分线给出 ∠IBC+∠ICB=65°。','在 △BIC 中，∠BIC=180°−65°=115°。']));
T('1.1','中线、高与面积分割','中线连接顶点与对边中点；高是顶点到对边所在直线的垂线段。','面积比较先找同高或同底关系，用底边比转化为面积比。','高可能在三角形外；中线通常不是高。',
Q('解答题','△ABC 面积为 24，AD 是中线，求 △ABD 面积。','12',['BD=DC，两三角形到 BC 的高相同，所以面积相等。','△ABD 面积=24÷2=12。']),
Q('填空题','△ABC 中 AD 是中线，BC=14，则 BD=____。','7',['D 是 BC 中点，BD=14÷2=7。']),
Q('解答题','D 在线段 BC 上，BD∶DC=2∶3，△ABC 面积为 40，求 △ABD、△ACD 的面积。','16；24',['同高三角形面积比等于底边比，即 2∶3。','面积分别为 40×2/5=16 和 40×3/5=24。']),
Q('解答题','△ABC 面积为 48，D 为 BC 中点，E 为 AD 中点，求 △BDE 与 △BEC 的面积。','12；24',['AD 将 △ABC 的面积平分，△BDA 面积为 24。','以 AD 为底比较，DE=AD/2，所以 △BDE 面积为 12；同理 △CDE 面积为 12。','△BEC 面积=12+12=24。']));
T('1.2','全等图形的对应关系','全等三角形的对应边、对应角分别相等。','按全等符号中的顶点顺序写出对应关系，再求值。','不能只凭摆放方向找对应边。',
Q('填空题','△ABC≌△DEF，AB=6，∠C=48°，求 DE、∠F。','6；48°',['A↔D，B↔E，C↔F。','AB 对应 DE，∠C 对应 ∠F，所以 DE=6，∠F=48°。']),
Q('选择题','△ABC≌△PQR，AC 的对应边是（　）。','B',['A↔P，C↔R，所以 AC 对应 PR。'],['PQ','PR','QR','不能确定']),
Q('计算题','△ABC≌△DEF，AB=2x+1，DE=11，BC=9，CA=7，求 x 和 △DEF 的周长。','x=5，周长 27',['2x+1=11，得 x=5。','全等三角形周长相等，周长=11+9+7=27。']),
Q('解答题','△ABC≌△DEF，∠A=(2x+10)°，∠D=(3x−20)°，∠B=∠F，求各角。','∠A=∠D=70°，其余四角均为 55°',['2x+10=3x−20，x=30，所以 ∠A=∠D=70°。','∠F=∠C，结合 ∠B=∠F 得 ∠B=∠C。','∠B=∠C=(180°−70°)÷2=55°，对应角同样为 55°。']));
T('1.3','SSS、SAS 与全等条件补充','SSS：三边对应相等；SAS：两边及其夹角对应相等。','列出已知条件，寻找公共边、对顶角或公共角。','SAS 的角必须是夹角；SSA 不能一般性判定全等。',
Q('证明题','四边形 ABCD 中 AB=AD，BC=DC。连接 AC，证明 △ABC≌△ADC。','△ABC≌△ADC（SSS）',['AB=AD，BC=DC，AC 为公共边。','三组对应边相等，所以 △ABC≌△ADC（SSS）。']),
Q('选择题','AB=DE、AC=DF，补充哪项可用 SAS 判定 △ABC≌△DEF？','A',['AB、AC 的夹角是 ∠A；DE、DF 的夹角是 ∠D。'],['∠A=∠D','∠B=∠E','∠C=∠F','∠B=∠F']),
Q('证明题','线段 AB、CD 相交于 O，OA=OB，OC=OD，证明 AC=BD。','AC=BD',['∠AOC=∠BOD（对顶角），OA=OB，OC=OD。','△AOC≌△BOD（SAS），对应边 AC=BD。']),
Q('证明题','△ABC 中 AB=AC，D、E 分别在线段 AB、AC 上，AD=AE。证明 BE=CD。','BE=CD',['比较 △ABE 与 △ACD：AB=AC，AE=AD。','∠BAE=∠CAD=∠BAC，为两组对应边的夹角。','△ABE≌△ACD（SAS），故 BE=CD。']));
T('1.3','ASA、AAS 与直角三角形全等','两角及夹边相等可用 ASA；两角及一角对边相等可用 AAS；直角三角形可用 HL。','识别公共边与平行线导出的角；使用 HL 前写明直角前提。','只有两角相等不足以推出全等。',
Q('证明题','△ABC 与 △DEF 中，∠B=∠E、∠C=∠F、BC=EF，说明全等理由。','△ABC≌△DEF（ASA）',['BC、EF 分别是两组相等角的夹边。','两角及夹边对应相等，故由 ASA 判定全等。']),
Q('选择题','两直角三角形的斜边和一条直角边分别相等，可用（　）判定全等。','C',['在直角三角形前提下，斜边和直角边分别相等满足 HL。'],['AAA','SSA','HL','不能判定']),
Q('证明题','AD⊥BC，D 在 BC 上，AB=AC，证明 BD=CD。','BD=CD',['△ABD、△ACD 都是直角三角形。','斜边 AB=AC，直角边 AD 公共。','由 HL 得 △ABD≌△ACD，所以 BD=CD。']),
Q('证明题','四边形 ABCD 中 AB∥CD，AD∥BC，连接 AC。证明 AB=CD，AD=BC。','AB=CD，AD=BC',['由平行线得 ∠BAC=∠DCA，∠BCA=∠DAC。','AC 为公共边，由 ASA 得 △BAC≌△DCA。','对应边相等，AB=CD，BC=DA。']));
T('1.4','尺规作图与作图依据','用无刻度直尺与圆规，根据给定边角条件定位第三顶点。','分析距离条件，用两弧交点定位，保留作图痕迹。','三边不满足三边关系时无法作出三角形。',
Q('作图题','已知三条线段长为 3、4、5，写出尺规作三角形的步骤。','以 5 为底，用半径 3、4 的弧定位第三顶点',['作 AB=5。','以 A、B 为圆心，以 3、4 为半径作弧，交于 C。','连接 AC、BC。SSS 保证所得三角形满足条件。']),
Q('选择题','尺规作图中的无刻度直尺用于（　）。','B',['无刻度直尺用来画直线、射线或线段；转移长度使用圆规。'],['读取长度','画直线或线段','测量角度','直接读取中点']),
Q('作图题','已知线段 AB，写出作其垂直平分线的尺规步骤。','连接两组等半径弧的交点',['分别以 A、B 为圆心，以同一大于 AB 一半的长度为半径，在 AB 两侧作弧，交于 P、Q。','连接 PQ。P、Q 均到 A、B 等距，所以 PQ 是 AB 的垂直平分线。']),
Q('解答题','用长为 4、7、c 的三条线段作三角形。分别讨论 c=3、5、11 时能否作成，并解释。','只有 c=5 可以',['第三边应满足 3＜c＜11。','c=5 满足，可作出两个关于底边对称的全等三角形。','c=3 或 11 时三点共线，两边之和等于第三边，不能作成非退化三角形。']));
T('1.5','利用全等测量不可达距离','构造全等三角形，将不可到达的线段转移为可测量的对应边。','确定目标边的对应边，再证明全等。','结论依赖构造条件，不能凭示意图猜等长。',
Q('解答题','AB、CD 相交于 O，OA=OB，OC=OD，测得 BD=18 米，求 AC。','18 米',['对顶角 ∠AOC=∠BOD，且 OA=OB，OC=OD。','△AOC≌△BOD（SAS），AC=BD=18 米。']),
Q('填空题','已证明 △ABC≌△DEF，河宽 AB 对应 DE，DE=24 米，则河宽为____米。','24',['全等三角形对应边相等，AB=DE=24 米。']),
Q('证明题','AB、CD 相交于 O，OA=OB，AC∥BD，证明 OC=OD。','OC=OD',['对顶角 ∠AOC=∠BOD；平行线给出 ∠OAC=∠OBD。','结合 OA=OB，由 ASA 得 △AOC≌△BOD。','所以 OC=OD。']),
Q('解答题','AB、CD 相交于 O，OA=OB，AC∥BD，实测 BD=32 米。求 AC；若删去平行条件，能否仍确定 AC？','原方案 AC=32 米；删去平行条件后不能确定',['由平行线和对顶角得两组角相等，结合 OA=OB，用 ASA 证明 △AOC≌△BOD。','因此 AC=BD=32 米。','仅保留一组边和一组角相等不足以判定全等，移动 C 可改变 AC。']));
